import{_ as o,a0 as s,w as a,s as p,I as e,x as t,a1 as r,A as n,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"何時使用 5G，何時使用 Wi-Fi 6 | LCTT x X-CMD","titleTemplate":false,"description":"何時使用 5G，何時使用 Wi-Fi 6 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"何時使用 5G，何時使用 Wi-Fi 6 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"何時使用 5G，何時使用 Wi-Fi 6 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20190612 When to use 5G, when to use Wi-Fi 6","title":"何時使用 5G，何時使用 Wi-Fi 6","tag":"202012","desc":""},"relativePath":"202012/20190612 When to use 5G, when to use Wi-Fi 6.md","filePath":"[post].md"}'),w={name:"202012/20190612 When to use 5G, when to use Wi-Fi 6.md"};function d(W,i,G,f,m,F){const l=s("Link");return a(),p("div",null,[i[28]||(i[28]=e("h1",{id:"何時使用-5g-何時使用-wi-fi-6",tabindex:"-1"},[t("何時使用 5G，何時使用 Wi-Fi 6 "),e("a",{class:"header-anchor",href:"#何時使用-5g-何時使用-wi-fi-6","aria-label":"Permalink to “何時使用 5G，何時使用 Wi-Fi 6”"},"​")],-1)),i[29]||(i[29]=e("blockquote",null,[e("p",null,"5G 是一種蜂窩服務, Wi-Fi 6 則是短程無線接入技術，這兩種技術都有使其在特定企業角色中發揮作用的特性。")],-1)),i[30]||(i[30]=e("p",null,[e("img",{src:"https://images.idgesg.net/images/article/2017/07/wi-fi_wireless_communication_network_abstract_thinkstock_610127984_1200x800-100730107-large.jpg",alt:"Thinkstock"})],-1)),e("p",null,[i[2]||(i[2]=t("我們已經看到了關於 ",-1)),r(l,{href:"https://www.networkworld.com/article/3203489/what-is-5g-how-is-it-better-than-4g.html"},{default:n(()=>[...i[0]||(i[0]=[t("5G",-1)])]),_:1}),i[3]||(i[3]=t(" 蜂窩還是 ",-1)),r(l,{href:"https://www.networkworld.com/article/3215907/why-80211ax-is-the-next-big-thing-in-wi-fi.html"},{default:n(()=>[...i[1]||(i[1]=[t("Wi-Fi 6",-1)])]),_:1}),i[4]||(i[4]=t(" 將在企業使用中勝出的大肆宣傳，但事實卻是這兩者在很大程度上互補，這將在 21 世紀 20 年代初形成一個有趣的競爭環境。",-1))]),i[31]||(i[31]=e("h3",{id:"_5g-在企業中的潛力",tabindex:"-1"},[t("5G 在企業中的潛力 "),e("a",{class:"header-anchor",href:"#_5g-在企業中的潛力","aria-label":"Permalink to “5G 在企業中的潛力”"},"​")],-1)),i[32]||(i[32]=e("p",null,"5G 對企業用户的承諾是在更低的延遲下提供更高的連接速度。蜂窩技術使用許可頻段，可在很大程度上消除未經許可的 WiFi 頻段可能會發生的潛在干涉。像當前的 4G LTE 技術一樣，5G 可以由蜂窩無線運營商提供，也可以作為專用網絡構建。",-1)),e("p",null,[i[6]||(i[6]=t("5G 的架構需要更多的無線接入點，並且在室內可能會出現連接質量較差或沒有連接。因此，典型的組織需要為連接它的 PC、路由器和其他設備評估其 ",-1)),r(l,{href:"https://www.networkworld.com/article/3330603/5g-versus-4g-how-speed-latency-and-application-support-differ.html"},{default:n(()=>[...i[5]||(i[5]=[t("當前 4G 和潛在 5G 服務配置",-1)])]),_:1}),i[7]||(i[7]=t("。部署室內微蜂窩、中繼器以及分佈式天線可以幫助解決室內 5G 服務問題。與 4G 一樣，5G 最佳的企業應用案例應該是用於真正的移動連接，例如，公共安全車和非地毯式覆蓋區域（如採礦，石油與天然氣開採、運輸、農業和一些製造業）。",-1))]),i[33]||(i[33]=e("p",null,"除了廣泛的移動性，5G 在漫遊時的身份驗證和部署速度方面也具有優勢，這正好滿足臨時辦公室或零售點的廣域網連接需求。5G 將會擁有在視頻直播這樣的數據擁塞的情況下分流的能力。隨着 5G 標準的成熟，該技術將提高其低功耗 IoT 連接的選擇。",-1)),i[34]||(i[34]=e("p",null,"未來四到五年內，5G 將從大城市和特定地區開始逐步推出；4G 技術將在未來數年內繼續流行。企業用户將需要新的設備、加密狗和路由器來連接 5G 服務。例如，蘋果的 iPhone 預計要到 2020 年才能支持 5G，而物聯網設備需要特定的蜂窩網絡兼容性才能連接到 5G。（LCTT 譯註：原文發表於 2019 年中）",-1)),i[35]||(i[35]=e("p",null,"Doyle Research 預計，5G 承諾的 1Gbps 和更高的帶寬將對 SD-WAN 市場產生重大影響。4G LTE 已經使蜂窩服務成為主要的 WAN 連接。5G 可能比許多有線 WAN 選項（例如 MPLS 或互聯網）更具成本競爭力或更便宜。5G 為企業 WAN 管理員提供了更多選擇，為他們的分支站點和遠程用户提供更多的帶寬 —— 隨着時間的推移，或將取代 MPLS。",-1)),i[36]||(i[36]=e("h3",{id:"wi-fi-6-在企業中的潛力",tabindex:"-1"},[t("Wi-Fi 6 在企業中的潛力 "),e("a",{class:"header-anchor",href:"#wi-fi-6-在企業中的潛力","aria-label":"Permalink to “Wi-Fi 6 在企業中的潛力”"},"​")],-1)),i[37]||(i[37]=e("p",null,"Wi-Fi 幾乎無處不在，它可以將便攜式筆記本電腦、平板電腦和其他設備連接到企業網絡中。Wi-Fi 6（802.11ax）是 Wi-Fi 的最新版本，並有望提高速度、降低延遲、改善聚合帶寬並提供高級流量管理。雖然 Wi-Fi 6 與 5G 有一些相似之處（兩者均基於正交頻分多址），但 Wi-Fi 6 不太容易受到干擾，能耗更低（延長設備電池的壽命），並提高了頻譜效率。",-1)),e("p",null,[i[9]||(i[9]=t("與典型的 Wi-Fi 相同，目前許多廠商都有 ",-1)),r(l,{href:"https://www.networkworld.com/article/3309439/80211ax-preview-access-points-and-routers-that-support-the-wi-fi-6-protocol-on-tap.html"},{default:n(()=>[...i[8]||(i[8]=[t("Wi-Fi 6 早期廠商專用版本",-1)])]),_:1}),i[10]||(i[10]=t("。Wi-Fi 聯盟計劃在 2020 年獲得 Wi-Fi 6 標準設備的認證。大多數企業將按照標準",-1)),i[11]||(i[11]=e("ruby",null,[t("接入點"),e("rt",null,"access-point")],-1)),i[12]||(i[12]=t("（AP）的生命週期（三年左右）升級到 Wi-Fi 6，除非他們有特定的性能/延遲要求，這將促使它們更快地升級。",-1))]),i[38]||(i[38]=u('<p>Wi-Fi 接入點仍然會受到干涉的影響。設計和配置接入點以提供適當的覆蓋範圍將會是一項挑戰。企業 LAN 管理者將繼續需要供應商提供的工具和合作夥伴來為組織配置最理想的 Wi-Fi 覆蓋。Wi-Fi 6 解決方案必須與有線區域基礎建設集成。Wi-Fi 供應商需要更好地為企業提供無線和有線解決方案的統一網絡管理。</p><h3 id="有線回程的需求" tabindex="-1">有線回程的需求 <a class="header-anchor" href="#有線回程的需求" aria-label="Permalink to “有線回程的需求”">​</a></h3><p>對於這兩種技術，通過無線與有線網絡基礎設施相結合，可以提供端到端的高速通信。在企業中，Wi-Fi 通常與區域和一些較大分支機構的有線以太網交換機搭配使用。一些設備通過電纜連接到交換機，其他設備則通過 Wi-Fi 連接，而筆記本電腦可能會同時採用這兩種方法。Wi-Fi 接入點通過企業內部的以太網連接，並通過光纖連接連接到 WAN 或 Internet。</p><p>5G 的架構廣泛使用光纖，將分佈式無線接入網絡連接回 5G 網絡的核心。光纖通常需要提供將 5G 端點連接到基於 SaaS 的應用程序所需的高帶寬，並提供實時視頻和高速互聯網訪問。專用 5G 網絡也必須滿足高速有線連接要求。</p><h3 id="切換問題" tabindex="-1">切換問題 <a class="header-anchor" href="#切換問題" aria-label="Permalink to “切換問題”">​</a></h3><p>隨着手機在 5G 和 Wi-Fi 6 之間切換，企業 IT 管理者要注意到切換挑戰。這些問題會影響到性能和用户滿意度。一些組織正在努力制定標準，以促進 Wi-Fi 6 和 5G 間更好的互操作性。 由於 Wi-Fi 6 的架構與 5G 接軌，在蜂窩網絡與 Wi-Fi 網絡間移動的體驗應該更加順滑。</p><h3 id="_5g-和-wi-fi-6-的對比取決於位置、應用和設備" tabindex="-1">5G 和 Wi-Fi 6 的對比取決於位置、應用和設備 <a class="header-anchor" href="#_5g-和-wi-fi-6-的對比取決於位置、應用和設備" aria-label="Permalink to “5G 和 Wi-Fi 6 的對比取決於位置、應用和設備”">​</a></h3><p>Wi-Fi 6 和 5G 在企業環境中的特定情況下相互競爭，這取決於位置、應用程序和設備類型。IT 管理者應該仔細評估他們當前和正在出現的連接性需求。Wi-Fi 將繼續佔領室內環境優勢，而移動蜂窩網絡將贏得更為廣泛的室外覆蓋。</p><p>一些重疊的情況發生在體育場館、酒店和其他大型活動場所，許多用户將爭奪帶寬。政府應用（包括智能城市方面）可適用於 Wi-Fi 和蜂窩。醫療保健設施中有許多分佈式醫療設備和需要連接的用户。大型分佈式製造環境具有相似的特點。新興的物聯網應用環境可能是最有趣的“重疊使用案例”。</p><h3 id="對於-it-領導者的建議" tabindex="-1">對於 IT 領導者的建議 <a class="header-anchor" href="#對於-it-領導者的建議" aria-label="Permalink to “對於 IT 領導者的建議”">​</a></h3><p>雖然支持它們的無線技術正在融合，但 Wi-Fi 6 和 5G 從根本上來説是不同的網絡，在企業連接中都有各自的作用。企業 IT 領導者應關注 Wi-Fi 和蜂窩網絡如何相互補足，Wi-Fi 將繼續作為內置技術，連接 PC 和筆記本電腦，處理手機和平板電腦數據，並實現一些物聯網連接。</p><p>4G LTE 升級到 5G 後，仍將是手機和平板電腦連接的真正移動技術，也是 PC 連接的一種選擇（通過加密狗），並在連接一些物聯網設備方面越來越受歡迎。5G WAN 鏈路將日益成為標準，作為提高 SD-WAN 可靠性的備份和遠程辦公室的主要鏈路。</p><hr>',13)),e("p",null,[i[14]||(i[14]=t("via: ",-1)),r(l,{href:"https://www.networkworld.com/article/3402316/when-to-use-5g-when-to-use-wi-fi-6.html"},{default:n(()=>[...i[13]||(i[13]=[t("https://www.networkworld.com/article/3402316/when-to-use-5g-when-to-use-wi-fi-6.html",-1)])]),_:1})]),e("p",null,[i[19]||(i[19]=t("作者：",-1)),r(l,{href:"https://www.networkworld.com/author/Lee-Doyle/"},{default:n(()=>[...i[15]||(i[15]=[t("Lee Doyle",-1)])]),_:1}),i[20]||(i[20]=t(" 選題：",-1)),r(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[16]||(i[16]=[t("lujun9972",-1)])]),_:1}),i[21]||(i[21]=t(" 譯者：",-1)),r(l,{href:"https://github.com/chenmu-kk"},{default:n(()=>[...i[17]||(i[17]=[t("chenmu-kk",-1)])]),_:1}),i[22]||(i[22]=t(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:n(()=>[...i[18]||(i[18]=[t("wxy",-1)])]),_:1})]),e("p",null,[i[25]||(i[25]=t("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[23]||(i[23]=[t("LCTT",-1)])]),_:1}),i[26]||(i[26]=t(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:n(()=>[...i[24]||(i[24]=[t("Linux中國",-1)])]),_:1}),i[27]||(i[27]=t(" 榮譽推出",-1))])])}const x=o(w,[["render",d]]);export{k as __pageData,x as default};
